<script lang="ts">import type { Snippet } from 'svelte'; import type { OnValueChange } from '../shared/types.js'; import DialogRoot from '../dialog/DialogRoot.svelte'; import { DrawerState, type DrawerHandle, type DrawerSnapPoint, type DrawerSwipeDirection, setDrawerContext } from './drawer-context.svelte.js'; interface Props { children?: Snippet; open?: boolean; onOpenChange?: OnValueChange<boolean, 'swipe' | 'trigger-press' | 'outside-press' | 'escape-key' | 'close-press'>; swipeDirection?: DrawerSwipeDirection; snapPoints?: DrawerSnapPoint[]; snapPoint?: DrawerSnapPoint | null; onSnapPointChange?: OnValueChange<DrawerSnapPoint | null, 'swipe'>; modal?: boolean; handle?: DrawerHandle; } let { children, open = $bindable(false), onOpenChange, swipeDirection = 'down', snapPoints = [], snapPoint = $bindable(null), onSnapPointChange, modal = true, handle }: Props = $props(); const drawer = setDrawerContext(new DrawerState()); drawer.setOpen = (next, event, reason) => { open = next; onOpenChange?.(next, { reason: reason === 'swipe' ? 'swipe' : 'trigger-press', event }); }; drawer.setSnapPoint = (next, event) => { snapPoint = next; onSnapPointChange?.(next, { reason: 'swipe', event }); }; $effect.pre(() => { drawer.open = open; drawer.swipeDirection = swipeDirection; drawer.snapPoints = snapPoints; drawer.snapPoint = snapPoint ?? snapPoints[0] ?? null; if (handle && handle.open !== open) open = handle.open; }); $effect.pre(() => { if (handle) handle.open = open; });</script>
<DialogRoot bind:open {modal} onOpenChange={(next, details) => onOpenChange?.(next, details)}>{@render children?.()}</DialogRoot>
